real funcone (real x) {
  return(abs(x - 3));
}

real functwo (real x) {
  return(4 - abs(x - 1));
}

fill((3,0)--(4,1)--(1,4)--(0,3)--cycle,gray(0.7));
draw(graph(funcone,-0.5,4.5));
draw(graph(functwo,-0.5,4.5));
draw((-0.5,0)--(4.5,0));
draw((0,-0.5)--(0,4.5));

